 if(name==='transition'){const status=el.dataset.status;const labels={accepted:'Placement confirmed. Other requests for this spot were declined.',declined:'Request declined.',cancelled:'Request cancelled.',completed:'Partnership complete.'};if(status==='accepted'){modalOpen('Confirm this partnership?',`<p class="modal-copy">Accepting reserves this placement for the sponsor and locks the agreed race details and price. Other pending requests for the same spot will be declined.</p><div class="inline-actions">${button('Confirm partnership','confirm-accept','','data-id="'+e(el.dataset.id)+'"')}${button('Go back','close-modal','outline')}</div><p id="modal-error" class="error-text" role="alert"></p>`);return;}await data.transition(el.dataset.id,status);await refresh();await render();toast(labels[status]);return;}
