 if(name==='download-brief'){const b=state.snapshot.bookings.find(b=>b.id===el.dataset.id),r=b.listing;const text=['ATHLEET — PARTNERSHIP BRIEF',data.demo?'DEMO — FICTIONAL PARTNERSHIP':'',`Status: ${b.status}`,`Brand: ${b.brand_name}`,`Event: ${r.event_name}`,`Date: ${r.race_date}`,`Race location: ${r.location}`,`Distance: ${r.distance}`,`Placement: ${placementInfo(b.placement,r.outfit).label}`,`Visible during: ${r.phase}`,`Package price: ${money(b.price)}`,`Deliverables: ${b.deliverables}`,`Campaign and contact details: ${b.message}`,b.proof_url?`Event proof: ${b.proof_url}`:'','No payment is processed by this portal.'].filter(Boolean).join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='athleet-partnership.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
