document.addEventListener('click',async event=>{
 if(event.target.closest('.skip-link')){event.preventDefault();const content=document.querySelector('#content');content?.focus();content?.scrollIntoView();return;}
 const target=event.target.closest('[data-action],[data-zone],[data-view],[data-save],[data-auth-mode],[data-skin],[data-kit],[data-remove-social]');if(!target)return;
 try{
  if(target.dataset.zone){const z=target.dataset.zone;if(document.querySelector('#editor-preview')){const r=state.draft;r.placements=r.placements.includes(z)?r.placements.filter(v=>v!==z):[...r.placements,z];}else{const r=detailRace();if(!r||!r.placements.includes(z)||r.reserved.includes(z))return;state.selectedZone=z;}state.view=rearZone(z)?'back':'front';state.viewKey++;updateStudio();return;}
  if(target.dataset.view){state.view=target.dataset.view;state.viewKey++;updateStudio();return;}
  if(target.dataset.authMode){state.authMode=target.dataset.authMode;await render();return;}
  if(target.dataset.skin||target.dataset.kit){const key=target.dataset.skin?'skin':'kit';state.profile.avatar[key]=target.dataset[key];document.querySelectorAll('[data-'+key+']').forEach(b=>b.setAttribute('aria-pressed',b===target));updateStudio();return;}
  if(target.dataset.removeSocial!==undefined){state.profile.socials.splice(Number(target.dataset.removeSocial),1);state.profile.audience=null;document.querySelector('#profile-socials').innerHTML=socialRows();document.querySelector('#profile-audience').innerHTML=audienceMarkup();return;}
  target.disabled=true;
  if(target.dataset.save)await saveHeart(target.dataset.save);else await action(target.dataset.action,target);
 }catch(error){const inline=modal.open?document.querySelector('#modal-error'):null;if(inline)inline.textContent=error.message;else toast(error.message,true);}finally{target.disabled=false;const status=document.querySelector('#portrait-processing');if(status)status.textContent='';}
});
document.addEventListener('input',event=>{const el=event.target;
 if(el.dataset.crop){state.photoCrop[el.dataset.crop]=el.type==='checkbox'?el.checked:['guide','hairLength'].includes(el.dataset.crop)?el.value:Number(el.value);drawPortraitGuide(document.querySelector('#portrait-crop'),state.photoCrop);return;}
 if(el.dataset.filter!==undefined){state.filters[el.dataset.filter]=el.value;if(el.dataset.filter==='discipline'){state.filters.distance='';const select=document.querySelector('[data-filter=distance]');select.innerHTML='<option value="">Any distance</option>'+options(el.value?raceTypes[el.value]:[...new Set(Object.values(raceTypes).flat())],'');}document.querySelector('#discovery-results').innerHTML=resultsMarkup();return;}
 if(el.closest('#race-form')){
  if(el.name==='discipline'){const select=document.querySelector('[name=distance]');select.innerHTML=options(raceTypes[el.value],raceTypes[el.value][0]);}
  if(el.name==='discipline'||el.name==='distance'){const custom=document.querySelector('[name=distance]').value==='Custom distance';document.querySelector('#custom-distance-field').hidden=!custom;document.querySelector('[name=custom_distance]').required=custom;}
  readRace();updateStudio();return;
 }
 if(el.closest('#profile-form')){if(el.name==='measurement_units'){state.measurementUnits=el.value;document.querySelector('#measurements-fields').innerHTML=measurementsMarkup(state.profile);return;}if(['height_feet','height_inches'].includes(el.name)){const f=el.form.elements;f.height_feet.required=f.height_inches.value!=='';state.profile.height_cm=heightCentimeters(f.height_feet.value,f.height_inches.value);return;}if(['height_value','weight_value'].includes(el.name)){const height=el.name==='height_value',factor=state.measurementUnits==='metric'?1:height?2.54:.45359237;state.profile[height?'height_cm':'weight_kg']=el.value===''?null:Math.round(Number(el.value)*factor*100)/100;return;}if(el.dataset.socialPlatform!==undefined||el.dataset.socialHandle!==undefined){const index=Number(el.dataset.socialPlatform??el.dataset.socialHandle);state.profile.socials[index][el.dataset.socialPlatform!==undefined?'platform':'handle']=el.value;state.profile.audience=null;document.querySelector('#profile-audience').innerHTML=audienceMarkup();}else if(['build','gender','avatar_outfit'].includes(el.name)){state.profile.avatar[el.name==='avatar_outfit'?'outfit':el.name]=el.value;state.profile.avatar=normalizeAvatar(state.profile.avatar);if(el.name==='gender'){if(state.profile.avatar.gender==='male'&&state.profile.avatar.outfit==='sports-bra')state.profile.avatar.outfit='shirtless';if(state.profile.avatar.gender==='female'&&state.profile.avatar.outfit==='shirtless')state.profile.avatar.outfit='sports-bra';document.querySelector('[name=avatar_outfit]').innerHTML=outfitOptions(state.profile.avatar);}document.querySelector('#outfit-advice').textContent=outfitAdvice(state.profile.avatar.outfit);updateStudio();}else if(['display_name','bio','location'].includes(el.name))state.profile[el.name]=el.value;return;}
 if(el.id==='brand-preview-text'){state.brand=el.value;updateStudio();}
});
document.addEventListener('change',async event=>{if(event.target.id!=='logo-upload')return;const file=event.target.files[0];if(!file)return;const listing=state.detailId;try{const blob=await prepareArtwork(file);if(listing!==state.detailId||!event.target.isConnected)return;if(state.logo)URL.revokeObjectURL(state.logo);state.logoFile=blob;state.logo=URL.createObjectURL(blob);updateStudio();}catch(error){event.target.value='';toast(error.message,true);}});
